import{_ as a,o as t,c as s,a5 as r}from"./chunks/framework.DrDMl0tG.js";const i="/assets/fluid_stream_anymal.CI-Beax3.png",u=JSON.parse('{"title":"Server Example: Fluid Stream with ANYmal","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/fluid_stream_anymal.md","filePath":"sections/examples/server/fluid_stream_anymal.md"}'),o={name:"sections/examples/server/fluid_stream_anymal.md"};function l(n,e,d,h,m,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="server-example-fluid-stream-with-anymal" tabindex="-1">Server Example: Fluid Stream with ANYmal <a class="header-anchor" href="#server-example-fluid-stream-with-anymal" aria-label="Permalink to &quot;Server Example: Fluid Stream with ANYmal&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>ANYmal stands across a stream 0.55 m deep, the water pushing on its side (<a href="./../../Fluids.html">Fluids</a>). The water holds part of its weight up and drags on its legs and body, and its joints hold the standing pose with PD control.</p><ul><li>A gentle stream leaves it standing.</li><li>Past about 1.2 m/s, the drag on its side tips it over. The water then carries it off downstream, rolling it along the bed.</li></ul><p>Once it reaches the end of the channel, or has lain fallen for four seconds, it stands up at the start again, and the example prints how often the stream has knocked it over.</p><p><img src="'+i+'" alt="ANYmal across a stream of 2 m/s, every half second from standing: it tips over and the stream carries it off"></p><p>ANYmal in a stream of 2 m/s, every half second from standing. Within a second the water tips it onto its side, and then carries it downstream.</p><h2 id="controlling-the-stream" tabindex="-1">Controlling the stream <a class="header-anchor" href="#controlling-the-stream" aria-label="Permalink to &quot;Controlling the stream&quot;">​</a></h2><p>The example adds a slider, <code>Stream speed [m/s]</code>, from 0 to 3 m/s (<code>RaisimServer::addSlider()</code>). The rayrai TCP viewer shows it in its <strong>Controls</strong> window, at the lower right of the view. Drag it past 1.2 m/s to see ANYmal knocked over. Each step, the example reads it with <code>RaisimServer::getSlider()</code> and sets the water&#39;s velocity with <code>World::setFluidVolume()</code>.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>fluid_stream_anymal</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/fluid_stream_anymal</span></span></code></pre></div><p>Connect <code>rayrai_tcp_viewer</code> to port 8080. On Windows, run <code>build-examples/bin/fluid_stream_anymal.exe</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>ANYmal stands across the current, so the stream pushes on its narrow side, as when a robot crosses a river. Its joints hold the standing pose with gains of 200 N m/rad and 5 N m s/rad.</li><li>The bed&#39;s friction is 1.2, that of a stony bed, so the feet grip and the robot tips over rather than sliding off upright.</li><li>The scene lives in <code>include/fluid_stream.hpp</code>, which it shares with <a href="./fluid_stream.html">Fluid Stream</a>.</li></ul>',16)])])}const f=a(o,[["render",l]]);export{u as __pageData,f as default};
